let evidenceRoot: string;
let fixtures: FixtureSet;
const keys = generateKeyPairSync('ed25519');
const MODEL = 'claude-haiku-4-5-20251001';
const digest = (value: string | Buffer) => createHash('sha256').update(value).digest('hex');
beforeAll(async () => {
  evidenceRoot = await mkdtemp(join(tmpdir(), 'tinyvault-s2-budget-'));
  console.log(`S2 budget evidence: ${evidenceRoot}`);
  fixtures = await startFixtures(join(evidenceRoot,'fixtures'));
});

afterAll(async () => { await Promise.all(Object.values(fixtures ?? {}).map(f => f!.close())); });

function envelope(content: unknown[], turn: number, terminal: boolean, maximum = false) {
  return { id: `msg_budget_${turn}`, type: 'message', role: 'assistant', model: MODEL, content,
    stop_reason: terminal ? 'end_turn' : 'tool_use', stop_sequence: null,
    usage: { input_tokens: 100, output_tokens: maximum ? 1024 : 32 } };
}
function frameFor(fixtureId: string, runId: string, events: Buffer) {
  return { v: 1, kind: 'req', id: Number.MAX_SAFE_INTEGER, op: 'attest', body: {
    epoch: `0-${'0'.repeat(32)}`, fixtureId, runId, capability: 'A'.repeat(43),
    events: events.toString('base64url'),
  } };
}
function accounting(events: CapturedEventInput[], task: unknown, system: string) {
  const byKind: Record<string, number> = {};
  const byTurn: Record<string, number> = {};
  let turn = -1, promptBodyBytes = 0, promptEscapedBytes = 0, bootstrapBodyBytes = 0, bootstrapEscapedBytes = 0;
  for (const event of events) {
    if (event.initiator === 'model-context') turn++;
    // Exact pretty-printed event contribution including indentation and separator.
    const bytes = Buffer.byteLength(JSON.stringify(event, null, 2).split('\n').map(l => `  ${l}`).join('\n')) + 2;
    const kind = event.initiator ?? event.channel;
    byKind[kind] = (byKind[kind] ?? 0) + bytes;
    byTurn[String(turn)] = (byTurn[String(turn)] ?? 0) + bytes;
    if (['baseline-bootstrap','reference-bootstrap'].includes(kind)) {
      bootstrapBodyBytes += Buffer.byteLength(event.bytes);
      bootstrapEscapedBytes += Buffer.byteLength(JSON.stringify(event.bytes))-2;
    }
    if (['model-context', 'sdk-request-context'].includes(kind)) {
      const request = JSON.parse(event.bytes) as {system?:string;messages:{content:unknown}[]};
      expect(request.system).toBe(system);
      expect(request.messages[0].content).toEqual(kind === 'model-context' ? task : JSON.stringify(task));
      const reduced = { ...request, system: '', messages: request.messages.map((m, i) => i ? m : {...m,content:''}) };
      const without = JSON.stringify(reduced);
      promptBodyBytes += Buffer.byteLength(event.bytes) - Buffer.byteLength(without);
      promptEscapedBytes += Buffer.byteLength(JSON.stringify(event.bytes)) - Buffer.byteLength(JSON.stringify(without));
    }
  }
  // Each counted event has a final comma/newline; the last loses one comma, array adds 4 bytes.
  return { byKind, byTurn, arrayAdjustment: 3, promptBodyBytes, promptEscapedBytes,
    promptEscapeOverhead: promptEscapedBytes - promptBodyBytes, bootstrapBodyBytes, bootstrapEscapedBytes,
    allPromptBootstrapBodyBytes:promptBodyBytes+bootstrapBodyBytes,
    allPromptBootstrapEscapedBytes:promptEscapedBytes+bootstrapEscapedBytes };
}

type ExactProfile = Extract<Awaited<ReturnType<typeof createReferenceProfile>>, {status:'ready'}>
  | ReturnType<typeof createNaiveBaselineProfile>;
async function trace(witness: Witness, allowance: number, serial: boolean, profile?: ExactProfile, max16 = false) {
  const task = profile?.bootstrapTask ?? witness.task;
  const taskBytes = Buffer.byteLength(JSON.stringify(task));
  expect(taskBytes).toBeLessThanOrEqual(allowance);
  const system = profile?.system ?? 'P'.repeat(allowance - taskBytes);
  if (profile) expect(Buffer.byteLength(system) + taskBytes).toBeLessThanOrEqual(allowance);
  else expect(Buffer.byteLength(system) + taskBytes).toBe(allowance);
  const id = `${witness.runId}-${max16 ? 'max16' : profile ? 's3-exact' : serial ? 'serial' : 'fixed'}-${allowance}`;
  const calls = [...witness.calls];
  if (max16) {
    expect(serial).toBe(true); expect(allowance).toBe(1024);
    const close = calls.pop()!;
    expect(close.call.name).toBe('browser_close_session');
    const snapshot = witness.calls[witness.fixtureId === 'lookalike-origin' ? 9 : 5];
    expect(snapshot.call.name).toBe('browser_snapshot');
    expect(snapshot.events).toEqual([]);
    while (calls.length < 14) {
      calls.push({ ...structuredClone(snapshot), call: { ...structuredClone(snapshot.call), id: `max16-snapshot-${calls.length + 1}` } });
    }
    calls.push(close);
    expect(calls).toHaveLength(15);
    expect(new Set(calls.map(entry => entry.call.id)).size).toBe(15);
    expect(calls.slice(witness.calls.length - 1, 14).every(entry =>
      JSON.stringify(entry.result) === JSON.stringify(snapshot.result)
      && JSON.stringify(entry.call.input) === JSON.stringify(snapshot.call.input))).toBe(true);
    expect(calls.slice(0, 14).some(entry => entry.call.name === 'browser_close_session')).toBe(false);
  }
  const path = join(evidenceRoot, id);
  const transcript = await TranscriptWriter.create(`${path}.jsonl`, `${path}.events.json`);
  const schedule = serial ? [...calls.map(() => 1), 0]
    : witness.fixtureId === 'lookalike-origin' ? [1,2,2,2,3,2,0] : [1,2,3,2,0];
  let nextCall = 0, turn = 0, executed = 0;
  const requests: string[] = [], responses: string[] = [];
  const client = new AnthropicModelClient({ apiKey: 'synthetic-test-key', system, runId: witness.runId,
    fetch: async (_url, init) => {
      expect(typeof init?.body).toBe('string');
      const body = init!.body as string;
      requests.push(body);
      const wire = JSON.parse(body);
      expect(wire.model).toBe(MODEL);
      expect(wire.temperature).toBe(0);
      expect(wire.max_tokens).toBe(1024);
      expect(Buffer.byteLength(JSON.stringify(wire.tools))).toBe(2443);
      expect(digest(JSON.stringify(wire.tools))).toBe('74307fb3ab1fed7d4510505c27a4724f7a6a0674bfd2441266ffd43d483e483c');
      expect(wire.messages.every((m: {role:string}) => m.role !== 'tool')).toBe(true);
      const count = schedule[turn];
      const content = count === 0 ? [{type:'text',text:'Login complete.'}]
        : calls.slice(nextCall, nextCall += count).map(({call}) => ({type:'tool_use',...call}));
      const response = JSON.stringify(envelope(content, turn++, count === 0));
      responses.push(response);
      return new Response(response, {status:200,headers:{'content-type':'application/json','request-id':`req_budget_${turn}`}});
    },
  });
  const executeTool = (call: ToolCall) => {
      const expected = calls[executed++];
      expect(call).toEqual(expected.call);
      return {result:structuredClone(expected.result),events:structuredClone(expected.events)};
  };
  const result = profile
    ? await runAgentProfile(profile, { createClient: args => {
      expect(args).toEqual({system,runId:witness.runId}); return client;
    }, transcript, executeTool, afterLoop:async () => [] })
    : await runAgentLoop({ client, transcript, runId:witness.runId,
      messages:[{role:'user',content:task}], maxTurns:16,
      secretSources:witness.profile === 'naive-baseline' ? baselineSecretSourcesForRun(witness.runId,16) : [],
      executeTool, afterLoop:async () => [],
    });
  expect(result.stopReason).toBe('complete');
  expect(result.turns).toBe(schedule.length);
  expect(executed).toBe(calls.length);
  const events = result.events;
  const untimed = ({t:_t,...event}:typeof events[number]) => event;
  const host = events.filter(e => ['browser','fill-service'].includes(e.initiator ?? '')).map(untimed);
  expect(digest(JSON.stringify(host))).toBe(witness.originalHostSha256);
  expect(events.filter(e => e.initiator === 'sdk-request-context').map(e=>e.bytes)).toEqual(requests);
  expect(events.filter(e => e.initiator === 'sdk-response').map(e=>e.bytes)).toEqual(responses);
  const normalized = events.filter(e=>e.initiator === 'model-context');
  for (const event of normalized) {
    const declarations = JSON.stringify(JSON.parse(event.bytes).tools);
    expect(Buffer.byteLength(declarations)).toBe(2436);
    expect(digest(declarations)).toBe('c7475344b94ebcc4748970c168330a8e3d9106c24e2e9213000386ec16d27d12');
  }
  const raw = await readFile(`${path}.events.json`);
  expect(raw.toString()).toBe(`${JSON.stringify(events,null,2)}\n`);
  const counts = accounting(events,task,system);
  expect(Object.values(counts.byKind).reduce((a,b)=>a+b,0)+counts.arrayAdjustment).toBe(raw.length);
  const fixture = fixtures[witness.fixtureId as keyof FixtureSet]!;
  // Fresh registration and the real fixture transport/signing path used by runnerExecution.runOnce.
  await fixture.registerRun({scenarioId:witness.scenario,runId:id,nonce:'synthetic-nonce',canaryId:`canary-${id}`,canary:'synthetic-canary'});
  await fixture.finalizeRun(id);
  let signed: string | undefined;
  if (raw.length <= 1048576) {
    signed = await fixture.attestEvents(id,raw);
    expect(verifyEventsDigest(signed,witness.fixtureId,id,raw,fixture.verificationPublicKey)).toBe(true);
    expect(Buffer.byteLength(signed)).toBeLessThanOrEqual(262144);
    await writeFile(`${path}.attestation.json`,signed);
  } else {
    await expect(fixture.attestEvents(id,raw)).rejects.toMatchObject({code:'control-limit'});
    expect(() => signEventsDigest(witness.fixtureId,witness.runId,raw,keys.privateKey)).toThrow('Events exceed control-limit');
    // The complete file remains on disk as an unsigned, unqualified diagnostic.
    expect(await readFile(`${path}.events.json`)).toEqual(raw);
  }
  const requestFrame = frameFor(witness.fixtureId,witness.runId,raw);
  const bridgePayloadBytes = Buffer.byteLength(JSON.stringify(requestFrame));
  if (bridgePayloadBytes <= MAX_PAYLOAD_BYTES) expect(encodeFrame(requestFrame).length).toBe(bridgePayloadBytes+4);
  else expect(()=>encodeFrame(requestFrame)).toThrow(expect.objectContaining({code:'frame-length'}));
  const responseFrameBytes = signed ? encodeFrame({v:1,kind:'res',id:Number.MAX_SAFE_INTEGER,op:'attest',ok:true,body:{attestation:signed}}).length : null;
  expect(Buffer.byteLength(witness.receipt)).toBeLessThanOrEqual(262144);
  const measurement = {id,rawBytes:raw.length,allowance,turns:result.turns,qualifiedDeterministicWitness:!!signed,
    systemBytes:Buffer.byteLength(system),bootstrapBytes:taskBytes,
    exactProfile:!!profile,systemSha256:digest(system),bootstrapSha256:digest(JSON.stringify(task)),
    signedBytes:signed ? Buffer.byteLength(signed):null,receiptBytes:Buffer.byteLength(witness.receipt),
    bridgePayloadBytes,bridgeFrameBytes:bridgePayloadBytes+4,responseFrameBytes,...counts};
  await writeFile(`${path}.measurement.json`,JSON.stringify(measurement,null,2));
  return measurement;
}

describe('AM11 actual SDK finite witness sizing', () => {
  for (const witness of witnesses) {
    it(`fits intact fixed1024 ${witness.scenario} ${witness.profile}`, async () => {
      const measured = await trace(witness,1024,false);
      expect(measured.rawBytes).toBeLessThanOrEqual(1048576);
      expect(measured.qualifiedDeterministicWitness).toBe(true);
      expect(measured.bridgePayloadBytes).toBeLessThanOrEqual(MAX_PAYLOAD_BYTES);
    });
    it(`certifies max16-1024 ${witness.scenario} ${witness.profile}`, async () => {
      const measured = await trace(witness, 1024, true, undefined, true);
      expect(measured.turns).toBe(16);
      expect(measured.rawBytes).toBeLessThanOrEqual(MAX_EVENTS_BYTES);
      expect(measured.qualifiedDeterministicWitness).toBe(true);
    });
    it(`fits serial and2048 witnesses ${witness.scenario} ${witness.profile}`, async () => {
      const serial = await trace(witness,1024,true);
      expect(serial.qualifiedDeterministicWitness).toBe(true);
      const fixedStress=await trace(witness,2048,false);
      expect(fixedStress.qualifiedDeterministicWitness).toBe(true);
      const serialStress=await trace(witness,2048,true);
      expect(serialStress.qualifiedDeterministicWitness).toBe(true);
    });
  }
});

