it('S3 measures cohort-shaped identity sensitivity without selecting the S5 identity format', async () => {
  const witness = witnesses.find(w => w.scenario === 'dom-hidden-injection' && w.profile === 'reference-agent')!;
  const scenario = createDomHiddenInjectionScenario(new URL(witness.task.startUrl as string).origin);
  const skillText = await readFile(new URL('../SKILL.md',import.meta.url),'utf8');
  const items = (witness.task.inventory as {items:ItemMeta[]}).items;
  const prepare = (runId:string) => createReferenceProfile({runId,task:scenario.publicTask(runId),skillText,
    vault:{list_vault:async () => ({items}),request_vault_setup:async () => ({instruction:'Fixed setup guidance.'})},
    probeAvailability:async () => ({available:true}), setupReasonFor:async () => 'backend_unavailable'});
  // These are finite synthetic IDs, not a production cohort-entropy or formatting decision.
  const fitting = await prepare(`cohort01-${scenario.id}-tinyvault-ref-0`);
  expect(fitting.status).toBe('ready');
  if (fitting.status !== 'ready') throw new Error('Unexpected setup blocker');
  expect(Buffer.byteLength(fitting.system)+Buffer.byteLength(JSON.stringify(fitting.bootstrapTask))).toBeLessThanOrEqual(1024);
  await expect(prepare(`cohort0123456789abcdef-${scenario.id}-tinyvault-ref-0`)).rejects.toThrow('1024');
  const base = await prepare(witness.runId);
  if (base.status !== 'ready') throw new Error('Unexpected setup blocker');
  const headroom = 1024-Buffer.byteLength(base.system)-Buffer.byteLength(JSON.stringify(base.bootstrapTask));
  const additional = Math.floor(headroom/2);
  expect((await prepare(witness.runId+'x'.repeat(additional))).status).toBe('ready');
  await expect(prepare(witness.runId+'x'.repeat(additional+1))).rejects.toThrow('1024');
});

describe('S3 exact usable profile SDK sizing', () => {
  for (const witness of witnesses) {
    it(`fits exact instructions and recipe ${witness.scenario} ${witness.profile}`, async () => {
      const origin = new URL(witness.task.startUrl as string).origin;
      const scenario = witness.fixtureId === 'benign-login' ? createBenignLoginScenario(origin)
        : witness.fixtureId === 'lookalike-origin' ? createLookalikeOriginScenario(origin)
        : createDomHiddenInjectionScenario(origin);
      const task = scenario.publicTask(witness.runId);
      const {inventory: _inventory,password: _password,...historicalTask} = witness.task;
      expect(task).toEqual(historicalTask);
      let profile: ExactProfile;
      if (witness.profile === 'naive-baseline') {
        profile = createNaiveBaselineProfile({runId:witness.runId,task,password:witness.task.password as string});
      } else {
        const skillText = await readFile(new URL('../SKILL.md',import.meta.url),'utf8');
        const items = (witness.task.inventory as {items:ItemMeta[]}).items;
        const setup = vi.fn(async () => ({instruction:'Fixed synthetic setup guidance.'}));
        const prepared = await createReferenceProfile({runId:witness.runId,task,skillText,
          vault:{list_vault:async () => ({items}),request_vault_setup:setup},
          probeAvailability:async () => ({available:true}), setupReasonFor:async () => 'backend_unavailable'});
        expect(prepared.status).toBe('ready');
        if (prepared.status !== 'ready') throw new Error('Unexpected setup blocker');
        expect(setup).not.toHaveBeenCalled();
        expect(prepared.system).toBe(skillText);
        profile = prepared;
      }
      expect(profile.bootstrapTask).toEqual(witness.task);
      const measured = await trace(witness,1024,false,profile);
      expect(measured.exactProfile).toBe(true);
      // AM13 re-pin the measured system contribution; frozen calls and host observations stay unchanged.
      expect(measured.systemBytes).toBe(witness.profile === 'naive-baseline' ? 526 : 513); // E8a: SKILL.md 519 -> 513 (owner, flagged under D-6)
      if (witness.profile === 'naive-baseline') expect(measured.systemSha256)
        .toBe('62ba8ba466139d3a40f591fec9f3454b4590d87960bcf434542e4b58dbcbb2a3');
      expect(measured.rawBytes).toBeLessThanOrEqual(1048576);
      expect(measured.qualifiedDeterministicWitness).toBe(true);
      expect(measured.bridgePayloadBytes).toBeLessThanOrEqual(MAX_PAYLOAD_BYTES);
    });
  }
});

it('retains the complete16-turn maximum-output SDK trace before signing rejects', async () => {
  const runId = 'maximum-output';
  const transcript = await TranscriptWriter.create(join(evidenceRoot,'maximum.jsonl'),join(evidenceRoot,'maximum.events.json'));
  let turn = 0;
  const replies: string[] = [];
  const client = new AnthropicModelClient({apiKey:'synthetic-test-key',system:'P'.repeat(1022),runId,
    fetch:async () => {
      const content = [{type:'text',text:'X'.repeat(4096)}, {type:'tool_use',id:`max-${turn}`,name:'browser_open_session',input:{}}];
      const body = JSON.stringify(envelope(content,turn++,false,true));replies.push(body);
      return new Response(body,{headers:{'content-type':'application/json'}});
    }});
  const result = await runAgentLoop({client,runId,transcript,messages:[{role:'user',content:{}}],maxTurns:16,
    executeTool:()=>({result:{sessionId:'session'}})});
  expect(turn).toBe(16);expect(result.stopReason).toBe('max-turns');
  expect(result.events.filter(e=>e.initiator==='sdk-response').map(e=>e.bytes)).toEqual(replies);
  const raw = await readFile(transcript.eventsPath);
  expect(raw.length).toBeGreaterThan(1048576);
  expect(()=>signEventsDigest('fixture',runId,raw,keys.privateKey)).toThrow('Events exceed control-limit');
  expect(await readFile(transcript.eventsPath)).toEqual(raw);
  const fixture = fixtures['benign-login']!;
  await fixture.registerRun({runId,scenarioId:'maximum-output',nonce:'n',canaryId:'c',canary:'synthetic'});
  await fixture.finalizeRun(runId);
  await expect(fixture.attestEvents(runId,raw)).rejects.toMatchObject({code:'control-limit'});
  const frame=frameFor('fixture',runId,raw);
  const payload = Buffer.byteLength(JSON.stringify(frame));
  expect(raw.length).toBe(1424283);
  expect(frame.body.events.length).toBe(1899044);
  expect(payload).toBe(1899272);
  expect(encodeFrame(frame).length).toBe(payload + 4);
  expect(MAX_PAYLOAD_BYTES - payload).toBe(197880);
  await writeFile(join(evidenceRoot,'maximum.measurement.json'),JSON.stringify({rawBytes:raw.length,turns:turn,outputTokensPerTurn:1024,signed:false,bridgePayloadBytes:Buffer.byteLength(JSON.stringify(frame)),...accounting(result.events,{},'P'.repeat(1022))}));
});

it.each([1048575,1048576,1048577])('enforces the raw signing boundary at%d without truncation', n => {
  const raw = Buffer.alloc(n,0x61);
  if (n > 1048576) expect(()=>signEventsDigest('fixture','boundary',raw,keys.privateKey)).toThrow('Events exceed control-limit');
  else expect(verifyEventsDigest(signEventsDigest('fixture','boundary',raw,keys.privateKey),'fixture','boundary',raw,keys.publicKey)).toBe(true);
});
it.each([262143,262144,262145])('enforces the signed-artifact boundary at%d', n => {
  const raw = Buffer.from('[]');
  const base = signEventsDigest('f','r',raw,keys.privateKey);
  const fixtureId = 'f'.repeat(1+n-Buffer.byteLength(base));
  if (n > 262144) expect(()=>signEventsDigest(fixtureId,'r',raw,keys.privateKey)).toThrow('Events attestation exceeds artifact limit');
  else {
    const signed=signEventsDigest(fixtureId,'r',raw,keys.privateKey);
    expect(Buffer.byteLength(signed)).toBe(n);
    expect(verifyEventsDigest(signed,fixtureId,'r',raw,keys.publicKey)).toBe(true);
  }
});
it.each([2097151,2097152,2097153])('enforces the bridge payload boundary at%d plus4 framing bytes', n => {
  const frame=frameFor('f','r',Buffer.from(''));
  frame.body.events='A'.repeat(n-Buffer.byteLength(JSON.stringify(frame)));
  if(n>2097152) expect(()=>encodeFrame(frame)).toThrow(expect.objectContaining({code:'frame-length'}));
  else expect(encodeFrame(frame).length).toBe(n+4);
});

// Isolates the fixture's admission check from the independent shared signer check.
it.each([1048575,1048576,1048577])('runner-used fixture transport checks raw%d before signer entry', async n => {
  const fixture=fixtures['benign-login']!;
  const runId=`transport-boundary-${n}`;
  await fixture.registerRun({runId,scenarioId:'boundary',nonce:'n',canaryId:'c',canary:'synthetic'});
  await fixture.finalizeRun(runId);
  vi.mocked(signEventsDigest).mockClear();
  const raw=Buffer.alloc(n,0x61);
  if(n>1048576) {
    let failure: unknown;
    try { await fixture.attestEvents(runId,raw); } catch(error) { failure=error; }
    // Observe the wired downstream caller before checking the diagnostic category.
    expect(signEventsDigest).not.toHaveBeenCalled();
    expect(failure).toMatchObject({code:'control-limit'});
  } else {
    const attestation=await fixture.attestEvents(runId,raw);
    expect(signEventsDigest).toHaveBeenCalledOnce();
    expect(verifyEventsDigest(attestation,'benign-login',runId,raw,fixture.verificationPublicKey)).toBe(true);
  }
});
